  /// 普攻
  /// </summary>
  [pbr::OriginalName("BATTLE_ACTION_ATTACK")] BattleActionAttack = 1,
  [pbr::OriginalName("BATTLE_ACTION_SKILL")] BattleActionSkill = 2,
  /// <summary>
  /// 防御:本回合受伤减半
  /// </summary>
  [pbr::OriginalName("BATTLE_ACTION_DEFEND")] BattleActionDefend = 3,
  /// <summary>
